import {
  createContext,
  useContext,
  useMemo,
  useState,
  type PropsWithChildren,
} from "react";
import { safeJsonParse } from "../../lib/utils";

const KEY = "appstore.favorites";
const FavoritesContext = createContext<{
  slugs: string[];
  isFavorite: (slug: string) => boolean;
  toggle: (slug: string) => void;
} | null>(null);

export function FavoritesProvider({ children }: PropsWithChildren) {
  const [slugs, setSlugs] = useState<string[]>(() =>
    safeJsonParse(localStorage.getItem(KEY), []),
  );
  const value = useMemo(
    () => ({
      slugs,
      isFavorite: (slug: string) => slugs.includes(slug),
      toggle: (slug: string) =>
        setSlugs((current) => {
          const next = current.includes(slug)
            ? current.filter((item) => item !== slug)
            : [...current, slug];
          localStorage.setItem(KEY, JSON.stringify(next));
          return next;
        }),
    }),
    [slugs],
  );
  return (
    <FavoritesContext.Provider value={value}>
      {children}
    </FavoritesContext.Provider>
  );
}

export function useFavorites() {
  const value = useContext(FavoritesContext);
  if (!value) throw new Error("FavoritesProvider가 필요합니다.");
  return value;
}
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import { describe, expect, it, vi } from "vitest";
import { AuthProvider } from "../app/providers";
import { FavoritesProvider } from "../features/apps/favorites";
import { MyAppsPage } from "./personal-pages";

function myApp(overrides: Record<string, unknown>) {
  return {
    id: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
    slug: "agent-hub",
    name: "Agent Hub",
    summary: "AI 에이전트 카탈로그",
    ...overrides,
  };
}

function renderMyApps(items: Record<string, unknown>[]) {
  const fetchMock = vi.fn().mockImplementation(() =>
    Promise.resolve(
      new Response(JSON.stringify({ items, total: items.length }), {
        status: 200,
        headers: { "content-type": "application/json" },
      }),
    ),
  );
  vi.stubGlobal("fetch", fetchMock);
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  render(
    <QueryClientProvider client={client}>
      <MemoryRouter initialEntries={["/my/apps"]}>
        <AuthProvider>
          <FavoritesProvider>
            <MyAppsPage />
          </FavoritesProvider>
        </AuthProvider>
      </MemoryRouter>
    </QueryClientProvider>,
  );
}

describe("My applications", () => {
  it("labels each card with the status the owner cannot otherwise see", async () => {
    renderMyApps([
      myApp({ status: "draft" }),
      myApp({
        id: "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
        slug: "flow-studio",
        name: "Flow Studio",
        status: "pending_review",
      }),
      myApp({
        id: "cccccccc-cccc-4ccc-8ccc-cccccccccccc",
        slug: "secure-vault",
        name: "Secure Vault",
        status: "archived",
      }),
    ]);

    const cards = await screen.findAllByRole("article");
    expect(cards).toHaveLength(3);
    expect(cards[0]).toHaveTextContent("초안");
    expect(cards[1]).toHaveTextContent("검토 대기");
    expect(cards[2]).toHaveTextContent("보관됨");
    expect(screen.queryByRole("alert")).toBeNull();
  });

  it("opens the edit screen from a card the public detail route would 404 on", async () => {
    renderMyApps([
      myApp({ status: "published", visibility: "public" }),
      myApp({
        id: "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
        slug: "flow-studio",
        name: "Flow Studio",
        status: "pending_review",
      }),
      myApp({
        id: "cccccccc-cccc-4ccc-8ccc-cccccccccccc",
        slug: "secure-vault",
        name: "Secure Vault",
        status: "published",
        visibility: "private",
      }),
    ]);

    // A published, public app still opens its catalog page.
    const published = await screen.findByRole("heading", {
      name: "Agent Hub",
    });
    expect(published.querySelector("a")).toHaveAttribute(
      "href",
      "/apps/agent-hub",
    );
    expect(
      screen.getByRole("link", { name: "Agent Hub 상세 보기" }),
    ).toHaveAttribute("href", "/apps/agent-hub");

    // /apps/{slug} serves only published, public apps, so the other two have
    // no page there: the name link goes to the owner's edit screen and the
    // 자세히 button, with nothing to show, is left out.
    for (const [name, id] of [
      ["Flow Studio", "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"],
      ["Secure Vault", "cccccccc-cccc-4ccc-8ccc-cccccccccccc"],
    ]) {
      const heading = screen.getByRole("heading", { name });
      expect(heading.querySelector("a")).toHaveAttribute(
        "href",
        `/my/apps/${id}/edit`,
      );
      expect(
        screen.queryByRole("link", { name: `${name} 상세 보기` }),
      ).toBeNull();
    }
  });

  it("shows why a rejected app was sent back", async () => {
    renderMyApps([
      myApp({
        status: "rejected",
        review: {
          id: "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
          appId: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
          status: "rejected",
          level: 1,
          reason: "서비스 URL이 사내망에서 열리지 않습니다.",
          reviewerName: "검토자 김",
          decidedAt: "2026-09-01T08:00:00Z",
        },
      }),
    ]);

    const notice = await screen.findByRole("alert");
    expect(notice).toHaveTextContent(
      "서비스 URL이 사내망에서 열리지 않습니다.",
    );
    expect(notice).toHaveTextContent("검토자 김");
    expect(notice).toHaveTextContent("1단계 검토");
  });

  it("keeps a superseded reason hidden once the app is back in review", async () => {
    renderMyApps([
      myApp({
        status: "pending_review",
        review: {
          id: "cccccccc-cccc-4ccc-8ccc-cccccccccccc",
          appId: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
          status: "pending",
          level: 1,
        },
      }),
    ]);

    expect(
      await screen.findByRole("heading", { name: "Agent Hub" }),
    ).toBeVisible();
    expect(screen.queryByRole("alert")).toBeNull();
  });
});
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { afterEach, describe, expect, it, vi } from "vitest";
import { AuthProvider } from "../app/providers";
import { FavoritesProvider } from "../features/apps/favorites";
import { AppDetailPage, AppsPage } from "./public-pages";

describe("Apps route state", () => {
  it("restores search, category and sort controls from the URL", async () => {
    const fetchMock = vi.fn().mockImplementation((input: RequestInfo | URL) => {
      const url = String(input);
      const payload = url.includes("/categories")
        ? [{ id: "ai", slug: "ai", name: "AI" }]
        : {
            items: [
              {
                id: "1",
                slug: "agent-hub",
                name: "Agent Hub",
                summary: "AI 에이전트 카탈로그",
                category: { id: "ai", slug: "ai", name: "AI" },
                status: "published",
              },
            ],
            total: 1,
            limit: 24,
            offset: 0,
          };
      return Promise.resolve(
        new Response(JSON.stringify(payload), {
          status: 200,
          headers: { "content-type": "application/json" },
        }),
      );
    });
    vi.stubGlobal("fetch", fetchMock);
    const client = new QueryClient({
      defaultOptions: { queries: { retry: false } },
    });

    render(
      <QueryClientProvider client={client}>
        <MemoryRouter
          initialEntries={["/apps?q=agent&category=ai&sort=trending"]}
        >
          <AuthProvider>
            <FavoritesProvider>
              <AppsPage />
            </FavoritesProvider>
          </AuthProvider>
        </MemoryRouter>
      </QueryClientProvider>,
    );

    expect(screen.getByLabelText("앱 검색")).toHaveValue("agent");
    expect(screen.getByLabelText("정렬")).toHaveValue("trending");
    await waitFor(() =>
      expect(screen.getByLabelText("카테고리")).toHaveValue("ai"),
    );
    expect(
      await screen.findByRole("heading", { name: "Agent Hub" }),
    ).toBeVisible();
    // Everything in the public catalog is published; only an owner's own
    // list labels cards with their status.
    expect(screen.queryByText("게시됨")).toBeNull();
    expect(
      fetchMock.mock.calls.some(([url]) => String(url).includes("q=agent")),
    ).toBe(true);
  });
});

describe("App detail introduction", () => {
  // jsdom reports 0 for both heights, which is also what it reports after
  // these stubs are put back, so the reset is the plain jsdom answer.
  const stubHeight = (name: "scrollHeight" | "clientHeight", value: number) =>
    Object.defineProperty(HTMLElement.prototype, name, {
      configurable: true,
      get: () => value,
    });
  afterEach(() => {
    stubHeight("scrollHeight", 0);
    stubHeight("clientHeight", 0);
  });

  const renderDetail = (description: string) => {
    vi.stubGlobal(
      "fetch",
      vi.fn().mockImplementation((input: RequestInfo | URL) => {
        const url = String(input);
        const payload = url.includes("/documents")
          ? { items: [] }
          : url.includes("/apps/agent-hub")
            ? {
                id: "1",
                slug: "agent-hub",
                name: "Agent Hub",
                summary: "AI 에이전트 카탈로그",
                description,
                status: "published",
              }
            : {};
        return Promise.resolve(
          new Response(JSON.stringify(payload), {
            status: 200,
            headers: { "content-type": "application/json" },
          }),
        );
      }),
    );
    const client = new QueryClient({
      defaultOptions: { queries: { retry: false } },
    });
    render(
      <QueryClientProvider client={client}>
        <MemoryRouter initialEntries={["/apps/agent-hub"]}>
          <AuthProvider>
            <FavoritesProvider>
              <Routes>
                <Route path="/apps/:slug" element={<AppDetailPage />} />
              </Routes>
            </FavoritesProvider>
          </AuthProvider>
        </MemoryRouter>
      </QueryClientProvider>,
    );
  };

  it("folds a long description away so what follows it stays on screen", async () => {
    // jsdom lays nothing out, so the overflow the clamp would produce in a
    // browser is stated here.
    stubHeight("scrollHeight", 600);
    stubHeight("clientHeight", 200);
    renderDetail("긴 소개 ".repeat(200));
    const intro = await screen.findByText(/긴 소개/);
    expect(intro).toHaveClass("is-clamped");

    await userEvent.click(screen.getByRole("button", { name: /더 보기/ }));
    expect(intro).not.toHaveClass("is-clamped");
    expect(screen.getByRole("button", { name: /접기/ })).toHaveAttribute(
      "aria-expanded",
      "true",
    );
  });

  it("leaves a short description alone", async () => {
    stubHeight("scrollHeight", 120);
    stubHeight("clientHeight", 200);
    renderDetail("한 줄짜리 소개");
    expect(await screen.findByText("한 줄짜리 소개")).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: /더 보기/ })).toBeNull();
  });
});
