func (s *Server) me(w http.ResponseWriter, r *http.Request) {
	WriteJSON(w, http.StatusOK, CurrentPrincipal(r.Context()).User)
}

// myAppItem carries the review that put an owned app in its current status.
// Owners have no reviews:read permission, so this is the only way the person
// who has to act on a rejection gets to read the reason for it.
type myAppItem struct {
	model.App
	Review *model.Review `json:"review,omitempty"`
}

func (s *Server) myApps(w http.ResponseWriter, r *http.Request) {
	principal := CurrentPrincipal(r.Context())
	limit, offset := pagination(r, 50, 100)
	page, err := s.repository.ListApps(r.Context(), model.AppListOptions{
		OwnerID: &principal.User.ID, IncludeAll: true, Limit: limit, Offset: offset, Sort: "updated",
	})
	if err != nil {
		WriteError(w, r, err)
		return
	}
	appIDs := make([]uuid.UUID, 0, len(page.Items))
	for _, app := range page.Items {
		appIDs = append(appIDs, app.ID)
	}
	latest, err := s.repository.LatestReviewsByApp(r.Context(), appIDs)
	if err != nil {
		WriteError(w, r, err)
		return
	}
	items := make([]myAppItem, 0, len(page.Items))
	for _, app := range page.Items {
		item := myAppItem{App: app}
		if review, ok := latest[app.ID]; ok {
			item.Review = &review
		}
		items = append(items, item)
	}
	WriteJSON(w, http.StatusOK, model.Page[myAppItem]{
		Items: items, Total: page.Total, Limit: page.Limit, Offset: page.Offset,
	})
}

func (s *Server) myFavorites(w http.ResponseWriter, r *http.Request) {
	limit, offset := pagination(r, 50, 100)
	page, err := s.repository.ListFavorites(r.Context(), CurrentPrincipal(r.Context()).User.ID, limit, offset)
	if err != nil {
		WriteError(w, r, err)
		return
	}
	WriteJSON(w, http.StatusOK, page)
}

func (s *Server) addFavorite(w http.ResponseWriter, r *http.Request) {
	id, err := uuid.Parse(chi.URLParam(r, "id"))
	if err != nil {
		WriteError(w, r, Validation("앱 ID가 올바르지 않습니다.", nil))
		return
	}
	if err != nil {
		return model.App{}, fmt.Errorf("update app category: %w", ErrInvalid)
	}
	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return model.App{}, normalizeError("begin app update", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	before, err := scanApp(tx.QueryRow(ctx, `SELECT `+appColumns+appFrom+` WHERE a.id = $1 FOR UPDATE OF a`, id))
	if err != nil {
		return model.App{}, normalizeError("lock updated app", err)
	}
	result, err := tx.Exec(ctx, `
		UPDATE apps SET category_id = $2, name = $3, slug = $4, summary = $5,
			description = $6, icon = $7, gradient = $8, service_url = $9,
			tags = $10, screenshots = $11, language = $12, framework = $13,
			supports_mcp = $14, supports_api = $15, team = $16,
			app_version = $17, visibility = $18, updated_at = now()
		WHERE id = $1`, id, categoryID, input.Name, input.Slug, input.Summary,
		input.Description, input.Icon, input.Gradient, input.ServiceURL,
		jsonValue(input.Tags), jsonValue(input.Screenshots), input.Language,
		input.Framework, input.SupportsMCP, input.SupportsAPI, input.Team,
		input.Version, input.Visibility)
	if err != nil {
		return model.App{}, normalizeError("update app", err)
	}
	if result.RowsAffected() == 0 {
		return model.App{}, fmt.Errorf("update app: %w", ErrNotFound)
	}
	// Changed content means the approval SecCheck gave no longer describes this
	// app, so the challenge rotates and the owner goes round again.
	if securityRelevantChange(before, input) {
		if err := rotateAppChallenge(ctx, tx, id); err != nil {
			return model.App{}, err
		}
	}
	if err := tx.Commit(ctx); err != nil {
		return model.App{}, normalizeError("commit app update", err)
	}
	return r.GetAppByID(ctx, id)
}

// AdminAppOverrides carries the catalog fields only an administrator can set:
// the ones the owner submission workflow decides on its own.
type AdminAppOverrides struct {
	Status   string
	Featured bool
	// FeaturedRank is nil when the app is unranked, which sorts it after every
	// ranked app by most recent change.
	FeaturedRank *int
}

// MaxFeaturedRank bounds the hand-set order so a typo cannot push an app past
// every other featured entry by a meaningless margin.
const MaxFeaturedRank = 9999

func (o AdminAppOverrides) normalize() (AdminAppOverrides, error) {
	o.Status = strings.TrimSpace(o.Status)
	if !validAppStatus(o.Status) {
		return AdminAppOverrides{}, fmt.Errorf("app status: %w", ErrInvalid)
	}
	if o.FeaturedRank != nil && (*o.FeaturedRank < 1 || *o.FeaturedRank > MaxFeaturedRank) {
		return AdminAppOverrides{}, fmt.Errorf("featured rank: %w", ErrInvalid)
	}
	return o, nil
}
